  "Lưu kế hoạch hiện tại vào lịch sử và bắt đầu danh sách ứng viên mới. Mentor đã nhận vẫn giữ vai trò; hệ thống không liên hệ ứng viên cũ. Hãy xử lý các lời mời đang chờ trước.": "Lưu kế hoạch hiện tại vào lịch sử và bắt đầu danh sách ứng viên mới. Mentor đã nhận vẫn giữ vai trò; hệ thống không liên hệ ứng viên cũ. Hãy xử lý các lời mời đang chờ trước.",
