  "Lưu nội dung làm việc trước, sau đó đối chiếu và xác nhận riêng. Chỉ phát hiện chính là bắt buộc; các mục không áp dụng (như bộ dữ liệu cho nghiên cứu lý thuyết) có thể để trống.": "Lưu nội dung làm việc trước, sau đó đối chiếu và xác nhận riêng. Chỉ phát hiện chính là bắt buộc; các mục không áp dụng (như bộ dữ liệu cho nghiên cứu lý thuyết) có thể để trống.",
