  "Các nhóm được ưu tiên hiển thị dựa trên lĩnh vực nghiên cứu, mối quan tâm và thông tin chuyên môn trong hồ sơ học thuật của bạn.": "Các nhóm được ưu tiên hiển thị dựa trên lĩnh vực nghiên cứu, mối quan tâm và thông tin chuyên môn trong hồ sơ học thuật của bạn.",
  "Các quyền trên chỉ được kích hoạt nếu chủ dự án chấp nhận nguyên vẹn đề nghị này. Thư viện bài báo, dữ liệu riêng tư và kênh chat nội bộ không tự động mở rộng.": "Các quyền trên chỉ được kích hoạt nếu chủ dự án chấp nhận nguyên vẹn đề nghị này. Thư viện bài báo, dữ liệu riêng tư và kênh chat nội bộ không tự động mở rộng.",
