  "Lưu ý: LumiGap hỗ trợ bảo toàn bằng chứng và điều phối đối soát; quyết định học thuật cuối cùng thuộc cơ sở đào tạo/nghiên cứu có thẩm quyền.": "Lưu ý: LumiGap hỗ trợ bảo toàn bằng chứng và điều phối đối soát; quyết định học thuật cuối cùng thuộc cơ sở đào tạo/nghiên cứu có thẩm quyền.",
  "Lưu ý: Lượt trích dẫn và độ đầy đủ siêu dữ liệu chỉ là thông tin ngữ cảnh thư mục, không phải thước đo trực tiếp về giá trị khoa học hay mức độ phù hợp với dự án.": "Lưu ý: Lượt trích dẫn và độ đầy đủ siêu dữ liệu chỉ là thông tin ngữ cảnh thư mục, không phải thước đo trực tiếp về giá trị khoa học hay mức độ phù hợp với dự án.",
  "Lưu ý: Tô sáng chỉ đánh dấu từ khóa trùng lặp với tiêu chí vòng để quét nhanh, không tự động kết luận mức độ phù hợp khoa học.": "Lưu ý: Tô sáng chỉ đánh dấu từ khóa trùng lặp với tiêu chí vòng để quét nhanh, không tự động kết luận mức độ phù hợp khoa học.",
